  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "PEMA, a small polar amide-containing drug, showed at least 80% absolute oral bioavailability in normal subjects, directly supporting high F for a structurally related amide-bearing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Odanacatib, which contains a sulfone and amide motifs similar to the query, had 70% absolute oral bioavailability at a 10 mg fasted dose, supporting high F.",
