    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin, a basic heterocyclic drug with an amide, had 57.8% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Vilazodone, a CNS-active drug with amide and basic amine features, had 72% absolute oral bioavailability with food, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Trazodone, a tricyclic-like CNS drug with a basic side chain, showed 91% absolute oral bioavailability in fasted men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Flupentixol, a tricyclic antipsychotic with a basic side chain, had mean systemic availability of 55% after oral administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Benazeprilat, despite being a polar carboxylic acid, had 27–28.5% absolute oral bioavailability, still above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values above 20%, mostly 30–90%, despite physicochemical features such as basic amines, amides, sulfones, and moderate polarity. The mixed physicochemical prior is outweighed by consistent direct bioavailability evidence, so the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
